DO $$ DECLARE sig text; def text; BEGIN FOREACH sig IN ARRAY ARRAY['get_public_profile_activity(text)','get_public_profile_cases(text)','get_public_profile_slugs()','get_public_profile_stats(text)'] LOOP def:=pg_get_functiondef(to_regprocedure('public.'||sig)); def:=replace(def,'p.public_profile_enabled = true','p.public_profile_enabled = true AND public.has_module_access(p.id, ''public_profile_enabled'')'); def:=replace(def,'pr.public_profile_enabled = true','pr.public_profile_enabled = true AND public.has_module_access(pr.id, ''public_profile_enabled'')'); IF sig='get_public_profile_stats(text)' THEN def:=replace(def,'AND public_profile_enabled = true','AND public_profile_enabled = true AND public.has_module_access(id, ''public_profile_enabled'')'); END IF; EXECUTE def; END LOOP; END $$;
REVOKE EXECUTE ON FUNCTION public.invite_subscriber_premium(uuid,uuid) FROM PUBLIC,anon;
COMMENT ON FUNCTION public.invite_subscriber_premium(uuid,uuid) IS 'Reviewed authenticated RPC: caller active Admin or Facilitator of the selected Premium meeting group; target active subscriber; maintains role, no attendance or points.';